import os
import re
from collections import defaultdict

# Functions defined in internal/
defined_functions = {}

for root, dirs, files in os.walk('/bench/repo/internal'):
    for file in files:
        if file.endswith('.go') and not file.endswith('_test.go'):
            filepath = os.path.join(root, file)
            with open(filepath, 'r', errors='ignore') as f:
                content = f.read()
                # Find exported functions
                for match in re.finditer(r'func \(([^)]*)\)\s+([A-Z]\w+)\(', content):
                    method_name = match.group(2)
                    if filepath not in defined_functions:
                        defined_functions[filepath] = []
                    defined_functions[filepath].append(method_name)
                for match in re.finditer(r'^func ([A-Z]\w+)\(', content, re.MULTILINE):
                    func_name = match.group(1)
                    if filepath not in defined_functions:
                        defined_functions[filepath] = []
                    defined_functions[filepath].append(func_name)

# Count calls to each function
call_counts = defaultdict(int)

for root, dirs, files in os.walk('/bench/repo'):
    for file in files:
        if file.endswith('.go'):
            filepath = os.path.join(root, file)
            with open(filepath, 'r', errors='ignore') as f:
                content = f.read()
                for func_file, funcs in defined_functions.items():
                    for func in set(funcs):
                        # Count calls
                        pattern = r'\b' + func + r'\('
                        count = len(re.findall(pattern, content))
                        call_counts[func] += count

# Sort by call count
sorted_funcs = sorted(call_counts.items(), key=lambda x: x[1], reverse=True)
for func, count in sorted_funcs[:30]:
    print(f"{func}: {count}")
